import{_ as a,a as r,b as e,c as i,d as o,e as n}from"./chunks/chat-setting-02.QfVwD9xB.js";import{_ as s}from"./chunks/chat.CwIZ8ihr.js";import{_ as l,o as d,c,a3 as h}from"./chunks/framework.D1iekJsc.js";const I=JSON.parse('{"title":"聊天","description":"MiniTavern 聊天與會話：開聊、流式回覆、續寫重生成、氣泡操作；手機上的 AI 角色扮演對話主界面。","frontmatter":{"title":"聊天","description":"MiniTavern 聊天與會話：開聊、流式回覆、續寫重生成、氣泡操作；手機上的 AI 角色扮演對話主界面。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"聊天 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 聊天與會話：開聊、流式回覆、續寫重生成、氣泡操作；手機上的 AI 角色扮演對話主界面。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/chat"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/chat"}]]},"headers":[],"relativePath":"zh-TW/manual/chat.md","filePath":"zh-TW/manual/chat.md","lastUpdated":1787809620000}'),p={name:"zh-TW/manual/chat.md"};function m(g,t,u,_,f,b){return d(),c("div",null,[...t[0]||(t[0]=[h('<h1 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h1><p>路徑：底部 Tab <strong>聊天</strong>；對話頁為單會話主界面。</p><h2 id="會話列表" tabindex="-1">會話列表 <a class="header-anchor" href="#會話列表" aria-label="Permalink to &quot;會話列表&quot;">​</a></h2><p><img src="'+a+'" alt="聊天列表"></p><ul><li>搜索、置頂、克隆、刪除會話。</li><li>可導出 / 導入<strong>聊天存檔</strong>（見 <a href="./backup">備份與存檔</a>）。</li></ul><h2 id="對話頁常用操作" tabindex="-1">對話頁常用操作 <a class="header-anchor" href="#對話頁常用操作" aria-label="Permalink to &quot;對話頁常用操作&quot;">​</a></h2><p><img src="'+s+'" alt="對話頁"></p><table tabindex="0"><thead><tr><th>操作</th><th>說明</th></tr></thead><tbody><tr><td>發送</td><td>用戶消息 → 請求模型 → 流式或完整顯示回覆</td></tr><tr><td>附件圖</td><td>輸入區加號 → 相冊 / 拍照（需模型或識圖流程支持）。普通附圖會進聊天；若本聊開了「回覆圖片」，智能/關鍵詞仍可觸發出圖，附圖當風格參考。若輸入是 <code>/imagine …</code>，附圖只作生圖參考，不會當成用戶消息發出</td></tr><tr><td><code>/imagine</code></td><td>斜槓生圖：主模型先分析是否與對話有關、要不要角色/用戶參考，再去生圖。張數僅此項讀取生圖設置。失敗會留下氣泡，可點重試</td></tr><tr><td>續寫</td><td>在當前助手回覆末尾繼續生成</td></tr><tr><td>重生成</td><td>替換最近助手回覆（以 UI 為準）</td></tr><tr><td>智能回覆</td><td>生成建議填入輸入框，不直接變成助手消息</td></tr><tr><td>取消</td><td>取消進行中的生成</td></tr><tr><td>重新開始</td><td>清空並按開場白重開</td></tr></tbody></table><p>開場白若有多條，開聊時可選擇。</p><h2 id="圖片-發送與氣泡" tabindex="-1">圖片：發送與氣泡 <a class="header-anchor" href="#圖片-發送與氣泡" aria-label="Permalink to &quot;圖片：發送與氣泡&quot;">​</a></h2><p>輸入區 <strong>+</strong> 打開附件菜單：相冊、拍照，以及生圖相關入口（需已配置生圖連接時可用）。</p><div class="shot-flow"><figure class="shot-step"><img src="'+r+'" alt="加號附件菜單"><figcaption>1 · 加號 · 相冊 / 拍照</figcaption></figure><figure class="shot-step"><img src="'+e+'" alt="圖文氣泡"><figcaption>2 · 附圖 + 文字發出</figcaption></figure></div><h2 id="氣泡菜單" tabindex="-1">氣泡菜單 <a class="header-anchor" href="#氣泡菜單" aria-label="Permalink to &quot;氣泡菜單&quot;">​</a></h2><p><img src="'+i+'" alt="氣泡菜單"></p><p>長按或菜單：複製、編輯、隱藏、刪除等。隱藏消息通常不再展示（對上下文的影響以實現為準）。</p><h2 id="聊天設置-按會話" tabindex="-1">聊天設置（按會話） <a class="header-anchor" href="#聊天設置-按會話" aria-label="Permalink to &quot;聊天設置（按會話）&quot;">​</a></h2><p>入口：對話頁右上角或設置入口 → <strong>聊天設置</strong>。</p><div class="shot-flow"><figure class="shot-step"><img src="'+o+'" alt="聊天設置入口"><figcaption>1 · 聊天設置</figcaption></figure><figure class="shot-step"><img src="'+n+'" alt="會話配置項"><figcaption>2 · 模型 / 世界書 / 正則等</figcaption></figure></div> | 子項（文案以 App 為準） | 作用 | |-------------------------|------| | 角色詳情 | 查看本聊角色快照 / 導出等 | | 用戶身份 | 跟隨默認人設或指定 | | 語言模型 | 跟隨默認語言模型或指定連接 / 參數 | | 生圖模型 | 跟隨默認生圖，或單獨選連接、生圖設置與關鍵詞規則 | | 正則 | 多選全局正則組；**空選 = 關閉** | | 世界書 | 多選全局世界書；**空選 = 不注入** | | 變量管理 | 本聊 / 全局宏變量 | | 前端渲染 | HTML / 腳本相關開關 | | 識圖與顯示 / 背景 | 識圖（圖片描寫、識人、歷史原圖深度）與聊天外觀 | | 導出存檔 | 導出本聊 ZIP | <h2 id="出錯時" tabindex="-1">出錯時 <a class="header-anchor" href="#出錯時" aria-label="Permalink to &quot;出錯時&quot;">​</a></h2><p>氣泡錯誤態可打開 <strong>查看詳情</strong>，對照 <a href="./errors">錯誤代碼排錯</a>。斜槓生圖失敗會留在原氣泡上，點重試即可再生成。</p>',21)])])}const q=l(p,[["render",m]]);export{I as __pageData,q as default};
